raw.docDesignBody = T("Gameplay structure, mechanics breakdowns, loop design, and system planning.", { "zh-CN": "游戏玩法结构、机制拆解、循环设计与系统规划。", "zh-TW": "遊戲玩法結構、機制拆解、循環設計與系統規劃。", ja: "ゲームプレイ構造、メカニクスの分解、ループ設計、システム計画。", ko: "게임플레이 구조, 메커니즘 분석, 루프 설계, 시스템 계획.", fr: "Structure du gameplay, analyses de mécaniques, conception de boucles et planification système.", de: "Spielstruktur, Mechanik-Aufschlüsselungen, Loop-Design und Systemplanung.", es: "Estructura de gameplay, análisis de mecánicas, diseño de bucles y planificación de sistemas.", ru: "Структура геймплея, разбор механик, дизайн циклов и системное планирование.", pt: "Estrutura de gameplay, análises de mecânicas, design de loops e planejamento de sistemas.", it: "Struttura del gameplay, analisi delle meccaniche, design dei loop e pianificazione dei sistemi.", nl: "Gameplay-structuur, mechaniek-uitwerkingen, loop-ontwerp en systeemplanning.", pl: "Struktura rozgrywki, analiza mechanik, projektowanie pętli i planowanie systemów.", tr: "Oynanış yapısı, mekanik analizleri, döngü tasarımı ve sistem planlama.", vi: "Cấu trúc lối chơi, phân tích cơ chế, thiết kế vòng lặp và lập kế hoạch hệ thống.", id: "Struktur gameplay, analisis mekanik, desain loop, dan perencanaan sistem.", uk: "Структура геймплею, розбір механік, дизайн циклів та системне планування.", el: "Δομή gameplay, ανάλυση μηχανικών, σχεδίαση βρόχων και προγραμματισμός συστημάτων.", cs: "Struktura hratelnosti, rozbor mechanik, návrh smyček a systémové plánování.", sv: "Spelstruktur, mekanikanalyser, loopdesign och systemplanering." });
raw.docLoreTitle = T("Lore Notes", { "zh-CN": "世界观笔记", "zh-TW": "世界觀筆記", ja: "世界観ノート", ko: "세계관 노트", fr: "Notes de lore", de: "Lore-Notizen", es: "Notas de lore", ru: "Заметки о лоре", pt: "Notas de lore", it: "Note sul lore", nl: "Lore-notities", pl: "Notatki o lore", tr: "Lore Notları", vi: "Ghi chú cốt truyện", id: "Catatan Lore", uk: "Нотатки про всесвіт", el: "Σημειώσεις Lore", cs: "Lore poznámky", sv: "Lore-anteckningar" });
raw.docLoreBody = T("Setting history, worldbuilding fragments, naming systems, and narrative references.", { "zh-CN": "设定历史、世界观碎片、命名系统与叙事参考。", "zh-TW": "設定歷史、世界觀碎片、命名系統與敘事參考。", ja: "設定の歴史、世界構築の断片、命名システム、物語の参照。", ko: "설정 역사, 세계관 조각, 명명 시스템, 서사 참고 자료.", fr: "Histoire de l'univers, fragments de worldbuilding, systèmes de nommage et références narratives.", de: "Setting-Geschichte, Worldbuilding-Fragmente, Namenssysteme und narrative Referenzen.", es: "Historia del setting, fragmentos de worldbuilding, sistemas de nombres y referencias narrativas.", ru: "История сеттинга, фрагменты ворлдбилдинга, системы именования и повествовательные референсы.", pt: "História do cenário, fragmentos de construção de mundos, sistemas de nomenclatura e referências narrativas.", it: "Storia del setting, frammenti di worldbuilding, sistemi di denominazione e riferimenti narrativi.", nl: "Setting-geschiedenis, worldbuilding-fragmenten, naamgevingssystemen en narratieve referenties.", pl: "Historia świata, fragmenty budowania świata, systemy nazewnictwa i odniesienia narracyjne.", tr: "Evren tarihi, dünya oluşturma parçacıkları, isimlendirme sistemleri ve anlatı referansları.", vi: "Lịch sử bối cảnh, mảnh ghép thế giới, hệ thống đặt tên và tài liệu tham khảo cốt truyện.", id: "Sejarah pengaturan, fragmen pembangunan dunia, sistem penamaan, dan referensi naratif.", uk: "Історія сеттінгу, фрагменти світобудування, системи іменування та наративні референси.", el: "Ιστορία σκηνικού, θραύσματα κατασκευής κόσμου, συστήματα ονοματοδοσίας και αφηγηματικές αναφορές.", cs: "Historie světa, fragmenty budování světa, systémy pojmenování a narativní reference.", sv: "Setting-historia, worldbuilding-fragment, namngivningssystem och narrativa referenser." });
