raw.updateDevlogBody = T("A living stream of progress, experiments, milestones, and production snapshots.", { "zh-CN": "进度、实验、里程碑与生产快照的实时流。", "zh-TW": "進度、實驗、里程碑與生產快照的即時流。", ja: "進捗、実験、マイルストーン、制作スナップショットの生の流れ。", ko: "진행 상황, 실험, 이정표, 제작 스냅샷의 생생한 흐름.", fr: "Un flux vivant de progrès, d'expérimentations, de jalons et de captures de production.", de: "Ein lebendiger Strom von Fortschritt, Experimenten, Meilensteinen und Produktionsschnappschüssen.", es: "Un flujo vivo de progreso, experimentos, hitos y capturas de producción.", ru: "Живой поток прогресса, экспериментов, вех и производственных снимков.", pt: "Um fluxo vivo de progresso, experimentos, marcos e capturas de produção.", it: "Un flusso vivo di progressi, esperimenti, traguardi e istantanee di produzione.", nl: "Een levende stroom van voortgang, experimenten, mijlpalen en productiesnapshots.", pl: "Żywy strumień postępów, eksperymentów, kamieni milowych i migawek produkcyjnych.", tr: "İlerleme, deneyler, dönüm noktaları ve üretim anlık görüntülerinin canlı akışı.", vi: "Luồng thông tin trực tiếp về tiến độ, thử nghiệm, cột mốc và ảnh chụp sản xuất.", id: "Aliran langsung kemajuan, eksperimen, tonggak sejarah, dan cuplikan produksi.", uk: "Живий потік прогресу, експериментів, етапів та виробничих знімків.", el: "Μια ζωντανή ροή προόδου, πειραμάτων, οροσήμων και στιγμιοτύπων παραγωγής.", cs: "Živý proud pokroku, experimentů, milníků a produkčních snímků.", sv: "En levande ström av framsteg, experiment, milstolpar och produktionsskärmdumpar." });
raw.updateReleaseTitle = T("Release Notes", { "zh-CN": "更新日志", "zh-TW": "更新日誌", ja: "リリースノート", ko: "릴리스 노트", fr: "Notes de version", de: "Versionshinweise", es: "Notas de lanzamiento", ru: "Примечания к релизу", pt: "Notas de lançamento", it: "Note di rilascio", nl: "Release-opmerkingen", pl: "Informacje o wydaniu", tr: "Sürüm Notları", vi: "Ghi chú phát hành", id: "Catatan Rilis", uk: "Примітки до релізу", el: "Σημειώσεις Έκδοσης", cs: "Poznámky k vydání", sv: "Versionsanteckningar" });
raw.updateReleaseBody = T("Patch notes, version summaries, feature additions, and change history.", { "zh-CN": "补丁说明、版本摘要、功能新增与变更历史。", "zh-TW": "補丁說明、版本摘要、功能新增與變更歷史。", ja: "パッチノート、バージョン概要、機能追加、変更履歴。", ko: "패치 노트, 버전 요약, 기능 추가, 변경 이력.", fr: "Notes de patch, résumés de version, ajouts de fonctionnalités et historique des modifications.", de: "Patchnotizen, Versionszusammenfassungen, Feature-Hinzufügungen und Änderungshistorie.", es: "Notas de parche, resúmenes de versión, adiciones de características e historial de cambios.", ru: "Патч-ноуты, сводки версий, добавление функций и история изменений.", pt: "Notas de patch, resumos de versão, adições de recursos e histórico de alterações.", it: "Note patch, riassunti versione, aggiunte di funzionalità e cronologia delle modifiche.", nl: "Patchnotities, versiesamenvattingen, toevoegingen van functies en wijzigingsgeschiedenis.", pl: "Notatki poprawek, podsumowania wersji, dodawanie funkcji i historia zmian.", tr: "Yama notları, sürüm özetleri, özellik eklemeleri ve değişiklik geçmişi.", vi: "Ghi chú bản vá, tóm tắt phiên bản, bổ sung tính năng và lịch sử thay đổi.", id: "Catatan patch, ringkasan versi, penambahan fitur, dan riwayat perubahan.", uk: "Патч-ноути, підсумки версій, додавання функцій та історія змін.", el: "Σημειώσεις patch, περιλήψεις εκδόσεων, προσθήκες λειτουργιών και ιστορικό αλλαγών.", cs: "Poznámky k opravám, shrnutí verzí, přidání funkcí a historie změn.", sv: "Patchanteckningar, versionssammanfattningar, funktionsadditioner och ändringshistorik." });
raw.updateNewsTitle = T("Studio News", { "zh-CN": "工作室新闻", "zh-TW": "工作室新聞", ja: "スタジオニュース", ko: "스튜디오 뉴스", fr: "Actualités du studio", de: "Studio-News", es: "Noticias del estudio", ru: "Новости студии", pt: "Notícias do estúdio", it: "Notizie dello studio", nl: "Studio-nieuws", pl: "Aktualności studia", tr: "Stüdyo Haberleri", vi: "Tin tức Studio", id: "Berita Studio", uk: "Новини студії", el: "Νέα Στούντιο", cs: "Zprávy studia", sv: "Studio-nyheter" });
raw.updateNewsBody = T("Announcements, roadmap moments, festival news, and public updates from the team.", { "zh-CN": "公告、路线图节点、展会新闻与团队公开更新。", "zh-TW": "公告、路線圖節點、展會新聞與團隊公開更新。", ja: "アナウンス、ロードマップの節目、フェスティバルニュース、チームからの公開アップデート。", ko: "공지사항, 로드맵 순간, 페스티벌 뉴스, 팀의 공개 업데이트.", fr: "Annonces, moments de feuille de route, nouvelles de festivals et mises à jour publiques de l'équipe.", de: "Ankündigungen, Roadmap-Momente, Festival-Neuigkeiten und öffentliche Updates vom Team.", es: "Anuncios, momentos de hoja de ruta, noticias de festivales y actualizaciones públicas del equipo.", ru: "Анонсы, этапы дорожной карты, фестивальные новости и публичные обновления от команды.", pt: "Anúncios, momentos de roteiro, notícias de festivais e atualizações públicas da equipe.", it: "Annunci, momenti della roadmap, notizie sui festival e aggiornamenti pubblici dal team.", nl: "Aankondigingen, roadmap-momenten, festivalnieuws en publieke updates van het team.", pl: "Ogłoszenia, momenty z planu działania, wiadomości z festiwali i publiczne aktualizacje zespołu.", tr: "Duyurular, yol haritası anları, festival haberleri ve ekipten kamuya açık güncellemeler.", vi: "Thông báo, các mốc lộ trình, tin tức lễ hội và cập nhật công khai từ nhóm.", id: "Pengumuman, momen peta jalan, berita festival, dan pembaruan publik dari tim.", uk: "Анонси, етапи дорожньої карти, фестивальні новини та публічні оновлення від команди.", el: "Ανακοινώσεις, στιγμές οδικού χάρτη, νέα φεστιβάλ και δημόσιες ενημερώσεις από την ομάδα.", cs: "Oznámení, milníky plánu, festivalové zprávy a veřejné aktualizace od týmu.", sv: "Tillkännagivanden, roadmap-ögonblick, festivalnyheter och offentliga uppdateringar från teamet." });
