raw.productLc300aTitle = T("LC300A · Luochuan OS", { "zh-CN": "LC300A · 落川操作系统", "zh-TW": "LC300A · 落川作業系統", ja: "LC300A · 洛川 OS", ko: "LC300A · Luochuan OS" });
raw.productLc300aDesc = T("An experimental Luochuan OS 300 platform exploring a bootable desktop system, apps, installer, packaging, and live ISO delivery.", { "zh-CN": "实验性的落川 OS 300 平台，探索可启动桌面系统、应用、安装器、软件包与 Live ISO 交付。", "zh-TW": "實驗性的落川 OS 300 平台，探索可啟動桌面系統、應用程式、安裝器、軟體包與 Live ISO 交付。", ja: "起動可能なデスクトップ、アプリ、インストーラー、パッケージ、Live ISO 配布を探る実験的な洛川 OS 300 プラットフォーム。", ko: "부팅 가능한 데스크톱, 앱, 설치 프로그램, 패키징 및 Live ISO 배포를 탐구하는 실험적 Luochuan OS 300 플랫폼입니다." });
