raw.gamePlayButton = T("Play Game", { "zh-CN": "开始游戏", "zh-TW": "開始遊戲", ja: "プレイ", ko: "게임 플레이", fr: "Jouer", de: "Spielen", es: "Jugar", ru: "Играть", pt: "Jogar" });
raw.gameBilliardsTitle = T("Billiards", { "zh-CN": "台球", "zh-TW": "撞球", ja: "ビリヤード", ko: "당구", fr: "Billard", de: "Billard", es: "Billar", ru: "Бильярд", pt: "Sinuca" });
raw.gameBilliardsDesc = T("A 3D billiards game with realistic physics and smooth controls. Line up your shots, apply spin, and sink every ball.", { "zh-CN": "一款具有真实物理效果和流畅操控的3D台球游戏。瞄准击球，施加旋转，将所有球打入袋中。", "zh-TW": "一款具有真實物理效果和流暢操控的3D撞球遊戲。瞄準擊球，施加旋轉，將所有球打入袋中。", ja: "リアルな物理演算と滑らかな操作感の3Dビリヤードゲーム。ショットを狙い、スピンをかけ、すべてのボールをポケットに入れよう。", ko: "현실적인 물리 효과와 부드러운 조작감의 3D 당구 게임. 샷을 조준하고, 스핀을 걸어 모든 공을 포켓에 넣으세요.", fr: "Un jeu de billard 3D avec une physique réaliste et des contrôles fluides. Visez vos coups, appliquez de l'effet et empochez chaque bille.", de: "Ein 3D-Billardspiel mit realistischer Physik und flüssiger Steuerung. Zielen Sie Ihre Stöße, geben Sie Effet und versenken Sie jede Kugel.", es: "Un juego de billar 3D con física realista y controles suaves. Apunta tus tiros, aplica efecto y encesta cada bola.", ru: "3D-бильярд с реалистичной физикой и плавным управлением. Прицеливайтесь, добавляйте вращение и забивайте каждый шар.", pt: "Um jogo de sinuca 3D com física realista e controles suaves. Mire seus tiros, aplique efeito e encaçape todas as bolas." });
raw.gameStellarDefenseTitle = T("Stellar Defense", { "zh-CN": "Stellar Defense", "zh-TW": "Stellar Defense", ja: "Stellar Defense", ko: "Stellar Defense", fr: "Stellar Defense", de: "Stellar Defense", es: "Stellar Defense", ru: "Stellar Defense", pt: "Stellar Defense" });
raw.gameStellarDefenseDesc = T("A bullet hell space shooter. Choose your difficulty, launch the mission, weave through fire, and defend the stars.", { "zh-CN": "一款弹幕太空射击游戏。选择难度，启动任务，在火力之间穿梭，守护星海。", "zh-TW": "一款彈幕太空射擊遊戲。選擇難度，啟動任務，在火力之間穿梭，守護星海。", ja: "弾幕系スペースシューター。難易度を選び、ミッションを開始し、弾幕をかいくぐって星々を守りましょう。", ko: "탄막 우주 슈팅 게임입니다. 난이도를 선택하고 미션을 시작해 포화를 피하며 별들을 방어하세요.", fr: "Un shooter spatial bullet hell. Choisissez la difficulté, lancez la mission, esquivez les tirs et défendez les étoiles.", de: "Ein Bullet-Hell-Weltraum-Shooter. Wähle den Schwierigkeitsgrad, starte die Mission, weiche dem Feuer aus und verteidige die Sterne.", es: "Un shooter espacial bullet hell. Elige dificultad, lanza la misión, esquiva el fuego y defiende las estrellas.", ru: "Космический bullet hell-шутер. Выберите сложность, запустите миссию, лавируйте под огнем и защищайте звезды.", pt: "Um shooter espacial bullet hell. Escolha a dificuldade, inicie a missão, desvie dos disparos e defenda as estrelas." });
raw.gameNeonSalvageTitle = T("Neon Salvage", { "zh-CN": "Neon Salvage", "zh-TW": "Neon Salvage", ja: "Neon Salvage", ko: "Neon Salvage", fr: "Neon Salvage", de: "Neon Salvage", es: "Neon Salvage", ru: "Neon Salvage", pt: "Neon Salvage" });
raw.gameNeonSalvageDesc = T("Pilot a salvage drone through neon debris fields. Collect shards, dodge wreckage, overclock your run, and survive each wave.", { "zh-CN": "驾驶回收无人机穿越霓虹残骸场。收集碎片，躲避废墟，超频冲刺，并撑过每一波。", "zh-TW": "駕駛回收無人機穿越霓虹殘骸場。收集碎片，躲避廢墟，超頻衝刺，並撐過每一波。", ja: "サルベージドローンを操り、ネオンの残骸地帯を進みます。シャードを集め、障害物を避け、オーバークロックして各ウェーブを生き延びましょう。", ko: "인양 드론을 조종해 네온 잔해 지대를 통과하세요. 조각을 모으고, 잔해를 피하고, 오버클럭하며 각 웨이브에서 살아남으세요.", fr: "Pilotez un drone de récupération dans des champs de débris néon. Collectez des fragments, évitez l'épave, surcadencez votre run et survivez aux vagues.", de: "Steuere eine Bergungsdrohne durch Neon-Trümmerfelder. Sammle Splitter, weiche Wracks aus, übertakte deinen Lauf und überlebe jede Welle.", es: "Pilota un dron de salvamento por campos de escombros neón. Recoge fragmentos, esquiva restos, acelera la carrera y sobrevive a cada oleada.", ru: "Управляйте спасательным дроном среди неоновых обломков. Собирайте осколки, уворачивайтесь от мусора, разгоняйте забег и переживайте волны.", pt: "Pilote um drone de salvamento por campos de destroços neon. Colete fragmentos, desvie de sucata, acelere a corrida e sobreviva a cada onda." });
raw.gameLumenDriftTitle = T("Lumen Drift", { "zh-CN": "Lumen Drift", "zh-TW": "Lumen Drift", ja: "Lumen Drift", ko: "Lumen Drift", fr: "Lumen Drift", de: "Lumen Drift", es: "Lumen Drift", ru: "Lumen Drift", pt: "Lumen Drift" });
raw.gameLumenDriftDesc = T("A luminous route-running arcade game. Link shards, pass gates, manage shield and overdrive, and keep the signal alive.", { "zh-CN": "一款光轨路线街机游戏。连接碎片，穿过门环，管理护盾与超载，让信号持续前进。", "zh-TW": "一款光軌路線街機遊戲。連接碎片，穿過門環，管理護盾與超載，讓訊號持續前進。", ja: "光のルートを走るアーケードゲーム。シャードをつなぎ、ゲートを通過し、シールドとオーバードライブを管理して信号を保ちましょう。", ko: "빛의 경로를 달리는 아케이드 게임입니다. 조각을 연결하고 게이트를 통과하며 실드와 오버드라이브를 관리해 신호를 유지하세요.", fr: "Un jeu d'arcade de routes lumineuses. Reliez les fragments, traversez les portes, gérez bouclier et overdrive, et gardez le signal vivant.", de: "Ein leuchtendes Routen-Arcade-Spiel. Verbinde Splitter, passiere Tore, verwalte Schild und Overdrive und halte das Signal am Leben.", es: "Un arcade de rutas luminosas. Conecta fragmentos, cruza puertas, gestiona escudo y sobrecarga, y mantén viva la señal.", ru: "Аркадная игра о световом маршруте. Соединяйте осколки, проходите ворота, управляйте щитом и ускорением, сохраняя сигнал.", pt: "Um arcade de rotas luminosas. Conecte fragmentos, passe por portais, gerencie escudo e overdrive, e mantenha o sinal vivo." });
raw.gameDoudizhuTitle = T("Doudizhu", { "zh-CN": "斗地主", "zh-TW": "鬥地主", ja: "闘地主", ko: "두더지", fr: "Doudizhu", de: "Doudizhu", es: "Doudizhu", ru: "Доудичжу", pt: "Doudizhu" });
raw.gameDoudizhuDesc = T("The classic Chinese card game. Play as landlord or farmer, use strategy and teamwork to outplay your opponents and win the round.", { "zh-CN": "经典中国扑克牌游戏。扮演地主或农民，运用策略与团队配合击败对手，赢取胜利。", "zh-TW": "經典中國撲克牌遊戲。扮演地主或農民，運用策略與團隊配合擊敗對手，贏取勝利。", ja: "中国のクラシックカードゲーム。地主または農民としてプレイし、戦略とチームワークで対戦相手を打ち負かし、ラウンドに勝利しましょう。", ko: "중국의 클래식 카드 게임입니다. 지주나 농민으로 플레이하여 전략과 팀워크로 상대를 이기고 승리하세요.", fr: "Le jeu de cartes chinois classique. Jouez en tant que propriétaire terrien ou fermier, utilisez la stratégie et le travail d'équipe pour surpasser vos adversaires et remporter la manche.", de: "Das klassische chinesische Kartenspiel. Spielen Sie als Landbesitzer oder Bauer, nutzen Sie Strategie und Teamwork, um Ihre Gegner zu schlagen und die Runde zu gewinnen.", es: "El clásico juego de cartas chino. Juega como terrateniente o campesino, usa estrategia y trabajo en equipo para superar a tus oponentes y ganar la ronda.", ru: "Классическая китайская карточная игра. Играйте помещиком или крестьянином, используйте стратегию и командную работу, чтобы переиграть противников и выиграть раунд.", pt: "O clássico jogo de cartas chinês. Jogue como proprietário ou camponês, use estratégia e trabalho em equipe para superar seus oponentes e vencer a rodada." });
raw.gameMahjongTitle = T("Mahjong", { "zh-CN": "麻将", "zh-TW": "麻將", ja: "麻雀", ko: "마작", fr: "Mahjong", de: "Mahjong", es: "Mahjong", ru: "Маджонг", pt: "Mahjong" });
raw.gameMahjongDesc = T("The classic Chinese tile-based game. Draw, discard, and declare winning hands across multiple regional rule sets.", { "zh-CN": "经典中国麻将游戏。摸牌、出牌，在多种地方规则下和牌取胜。", "zh-TW": "經典中國麻將遊戲。摸牌、出牌，在多種地方規則下胡牌取勝。", ja: "中国のクラシックな牌ゲーム。牌を引き、捨て、複数の地方ルールセットでアガリを宣言しましょう。", ko: "중국의 클래식 타일 게임입니다. 패를 뽑고 버리며 여러 지역 규칙에서 완성 패를 선언하세요.", fr: "Le jeu de tuiles chinois classique. Piochez, défaussez et déclarez des mains gagnantes selon plusieurs ensembles de règles régionales.", de: "Das klassische chinesische Steinespiel. Ziehen, ablegen und Gewinnhände über mehrere regionale Regelsätze hinweg erklären.", es: "El clásico juego de fichas chino. Roba, descarta y declara manos ganadoras en múltiples conjuntos de reglas regionales.", ru: "Классическая китайская игра на костях. Берите, сбрасывайте и объявляйте выигрышные комбинации по различным региональным правилам.", pt: "O clássico jogo de peças chinês. Compre, descarte e declare mãos vencedoras em vários conjuntos de regras regionais." });
raw.game24PointsTitle = T("24 Points", { "zh-CN": "24点", "zh-TW": "24點", ja: "24ポイント", ko: "24점", fr: "24 Points", de: "24 Punkte", es: "24 Puntos", ru: "24 Очка", pt: "24 Pontos" });
raw.game24PointsDesc = T("A fast-paced math card game. Use four numbers and basic operations to reach exactly 24. Race the clock and sharpen your mental arithmetic.", { "zh-CN": "快节奏数学卡牌游戏。运用四个数字和基本运算恰好算出24。与时间赛跑，锻炼心算能力。", "zh-TW": "快節奏數學卡牌遊戲。運用四個數字和基本運算恰好算出24。與時間賽跑，鍛鍊心算能力。", ja: "スピーディな数学カードゲーム。4つの数字と基本演算でちょうど24を作りましょう。時計と競争し、暗算力を鍛えます。", ko: "빠른 속도의 수학 카드 게임입니다. 4개의 숫자와 기본 연산으로 정확히 24를 만드세요. 시간과 경쟁하며 암산 능력을 sharpening하세요.", fr: "Un jeu de cartes mathématique rapide. Utilisez quatre nombres et des opérations de base pour atteindre exactement 24. Course contre la montre et affûtez votre calcul mental.", de: "Ein schnelles Mathe-Kartenspiel. Verwenden Sie vier Zahlen und Grundoperationen, um genau 24 zu erreichen. Rennen Sie gegen die Uhr und schärfen Sie Ihr Kopfrechnen.", es: "Un juego de cartas matemático rápido. Usa cuatro números y operaciones básicas para llegar exactamente a 24. Compite contra el reloj y afila tu aritmética mental.", ru: "Быстрая математическая карточная игра. Используйте четыре числа и базовые операции, чтобы получить ровно 24. Соревнуйтесь со временем и развивайте устный счет.", pt: "Um jogo de cartas matemático rápido. Use quatro números e operações básicas para chegar exatamente a 24. Corra contra o relógio e aguçe sua aritmética mental." });
raw.gameXiangQiTitle = T("XiangQi", { "zh-CN": "中国象棋", "zh-TW": "中國象棋", ja: "シャンチー", ko: "샹치", fr: "XiangQi", de: "XiangQi", es: "XiangQi", ru: "Сянци", pt: "XiangQi" });
raw.gameXiangQiDesc = T("The classic Chinese strategy board game. Command your pieces across the river, protect your general, and checkmate your opponent.", { "zh-CN": "经典中国策略棋类游戏。指挥你的棋子过河，保护你的老将，将死对手。", "zh-TW": "經典中國策略棋類遊戲。指揮你的棋子過河，保護你的老將，將死對手。", ja: "中国のクラシックな戦略ボードゲーム。川を渡って駒を指揮し、将軍を守り、相手を詰みましょう。", ko: "중국의 클래식 전략 보드 게임입니다. 강을 건너 기물을 지휘하고, 장군을 보호하며 상대를 체크메이트하세요.", fr: "Le jeu de plateau stratégique chinois classique. Commandez vos pièces à travers la rivière, protégez votre général et mettez votre adversaire échec et mat.", de: "Das klassische chinesische Strategie-Brettspiel. Befehligen Sie Ihre Figuren über den Fluss, schützen Sie Ihren General und setzen Sie Ihren Gegner schachmatt.", es: "El clásico juego de mesa de estrategia chino. Comanda tus piezas a través del río, protege a tu general y jaquea a tu oponente.", ru: "Классическая китайская стратегическая настольная игра. Командуйте фигурами через реку, защищайте генерала и ставьте мат противнику.", pt: "O clássico jogo de tabuleiro de estratégia chinês. Comande suas peças através do rio, proteja seu general e dê xeque-mate no oponente." });
raw.game2048OriginalTitle = T("2048 Original", { "zh-CN": "2048 原版", "zh-TW": "2048 原版", ja: "2048 オリジナル", ko: "2048 오리지널", fr: "2048 Original", de: "2048 Original", es: "2048 Original", ru: "2048 Оригинал", pt: "2048 Original" });
raw.game2048OriginalDesc = T("The classic number-merging puzzle. Slide tiles on a 4×4 grid, combine identical numbers, and reach the legendary 2048 tile.", { "zh-CN": "经典数字合并解谜游戏。在4×4网格上滑动方块，合并相同数字，达成传奇的2048方块。", "zh-TW": "經典數字合併解謎遊戲。在4×4網格上滑動方塊，合併相同數字，達成傳奇的2048方塊。", ja: "クラシックな数字合成パズル。4×4グリッドでタイルをスライドさせ、同じ数字を組み合わせて伝説の2048タイルを目指しましょう。", ko: "클식 숫자 병합 퍼즐입니다. 4×4 그리드에서 타일을 슬라이드하고 동일한 숫자를 합쳐 전설적인 2048 타일을 만드세요.", fr: "Le puzzle classique de fusion de nombres. Faites glisser les tuiles sur une grille 4×4, combinez les chiffres identiques et atteignez la légendaire tuile 2048.", de: "Das klassische Zahlen-Verschmelzungspuzzle. Schiebe Kacheln auf einem 4×4-Raster, kombiniere identische Zahlen und erreiche die legendäre 2048-Kachel.", es: "El clásico puzzle de fusión de números. Desliza fichas en una cuadrícula 4×4, combina números idénticos y alcanza la legendaria ficha 2048.", ru: "Классическая головоломка слияния чисел. Сдвигайте плитки на сетке 4×4, объединяйте одинаковые числа и достигните легендарной плитки 2048.", pt: "O clássico quebra-cabeça de fusão de números. Deslize peças em uma grade 4×4, combine números idênticos e alcance a lendária peça 2048." });
raw.game2048NewEraTitle = T("2048 New Era", { "zh-CN": "2048 新纪元", "zh-TW": "2048 新紀元", ja: "2048 ニューエラ", ko: "2048 뉴 에라", fr: "2048 New Era", de: "2048 New Era", es: "2048 New Era", ru: "2048 Новая Эра", pt: "2048 New Era" });
raw.game2048NewEraDesc = T("A modern reimagining of 2048 with fresh visuals and new mechanics. Merge tiles, unlock power-ups, and chase ever-higher numbers.", { "zh-CN": "2048的现代重制版，拥有全新视觉和新机制。合并方块，解锁强化道具，追求更高的数字。", "zh-TW": "2048的現代重製版，擁有全新視覺和新機制。合併方塊，解鎖強化道具，追求更高的數字。", ja: "新しいビジュアルと新メカニクスを備えた2048の現代版。タイルをマージし、パワーアップをアンロックして、さらに高い数字を目指しましょう。", ko: "새로운 비주얼과 새로운 메커닉을 갖춘 2048의 현대적 재구상. 타일을 병합하고, 파워업을 잠금 해제하며, 더 높은 숫자를 추구하세요.", fr: "Une réimagination moderne de 2048 avec des visuels frais et de nouvelles mécaniques. Fusionnez les tuiles, débloquez des power-ups et poursuivez des nombres toujours plus élevés.", de: "Eine moderne Neuinterpretation von 2048 mit frischem Design und neuen Mechaniken. Vereinige Kacheln, schalte Power-Ups frei und jag immer höhere Zahlen.", es: "Una reimaginación moderna de 2048 con visuales frescos y nuevas mecánicas. Fusiona fichas, desbloquea potenciadores y persigue números cada vez más altos.", ru: "Современная переосмысленная версия 2048 с новой графикой и механиками. Объединяйте плитки, открывайте усилители и гонитесь за все более высокими числами.", pt: "Uma reimaginação moderna do 2048 com visuais novos e novas mecânicas. Mescle peças, desbloqueie power-ups e persiga números cada vez mais altos." });
raw.gameSudokuTitle = T("Sudoku", { "zh-CN": "数独", "zh-TW": "數獨", ja: "数独", ko: "스도쿠", fr: "Sudoku", de: "Sudoku", es: "Sudoku", ru: "Судоку", pt: "Sudoku" });
raw.gameSudokuDesc = T("The timeless logic puzzle. Fill a 9×9 grid so that each row, column, and 3×3 box contains every digit from 1 to 9 exactly once.", { "zh-CN": "永恒的经典逻辑解谜游戏。填满9×9网格，使每行、每列和每个3×3宫格都恰好包含1到9的每个数字一次。", "zh-TW": "永恆的經典邏輯解謎遊戲。填滿9×9網格，使每行、每列和每個3×3宮格都恰好包含1到9的每個數字一次。", ja: "永遠のクラシックな論理パズル。9×9グリッドを埋め、各行、各列、各3×3ボックスに1から9までの数字がちょうど1つずつ含まれるようにしましょう。", ko: "영원한 클래식 논리 퍼즐입니다. 9×9 그리드를 채워 각 행, 열, 3×3 박스에 1부터 9까지의 숫자가 정확히 한 번씩 포함되도록 하세요.", fr: "Le puzzle logique intemporel. Remplissez une grille 9×9 de sorte que chaque ligne, colonne et boîte 3×3 contienne exactement une fois chaque chiffre de 1 à 9.", de: "Das zeitlose Logik-Puzzle. Fülle ein 9×9-Raster so, dass jede Zeile, Spalte und 3×3-Box jede Ziffer von 1 bis 9 genau einmal enthält.", es: "El puzzle lógico atemporal. Llena una cuadrícula 9×9 para que cada fila, columna y caja 3×3 contenga exactamente una vez cada dígito del 1 al 9.", ru: "Вневременная логическая головоломка. Заполните сетку 9×9 так, чтобы каждая строка, столбец и блок 3×3 содержали каждую цифру от 1 до 9 ровно один раз.", pt: "O quebra-cabeça lógico atemporal. Preencha uma grade 9×9 para que cada linha, coluna e caixa 3×3 contenha exatamente uma vez cada dígito de 1 a 9." });
raw.gameSubwaySurfersTitle = T("Subway Surfers", { "zh-CN": "地铁跑酷", "zh-TW": "地鐵跑酷", ja: "サブウェイサーファーズ", ko: "서브웨이 서퍼스", fr: "Subway Surfers", de: "Subway Surfers", es: "Subway Surfers", ru: "Subway Surfers", pt: "Subway Surfers" });
raw.gameSubwaySurfersDesc = T("An endless runner through subway tunnels. Dodge trains, collect coins, and see how far you can go.", { "zh-CN": "无尽跑酷穿越地铁隧道。躲避列车，收集金币，看看你能跑多远。", "zh-TW": "無盡跑酷穿越地鐵隧道。躲避列車，收集金幣，看看你能跑多遠。", ja: "地下鉄トンネルを駆け抜けるエンドレスランナー。電車を避け、コインを集め、どこまで走れるか挑戦しましょう。", ko: "지하철 터널을 달리는 무한 러너입니다. 열차를 피하고 동전을 모으며 얼마나 멀리 갈 수 있는지 도전하세요.", fr: "Un runner infini à travers les tunnels du métro. Esquivez les trains, collectez des pièces et voyez jusqu'où vous pouvez aller.", de: "Ein Endless Runner durch U-Bahn-Tunnel. Weiche Zügen aus, sammle Münzen und sieh, wie weit du kommen kannst.", es: "Un corredor sin fin por túneles de metro. Esquiva trenes, recolecta monedas y ve qué tan lejos puedes llegar.", ru: "Бесконечный раннер через туннели метро. Уворачивайтесь от поездов, собирайте монеты и проверьте, как далеко вы сможете зайти.", pt: "Um corredor infinito por túneis de metrô. Desvie de trens, colete moedas e veja até onde você pode chegar." });
raw.gamesMoreSoon = T("More games coming soon.", { "zh-CN": "更多游戏即将推出。", "zh-TW": "更多遊戲即將推出。", ja: "さらにゲームが近日公開予定。", ko: "더 많은 게임이 곧 출시됩니다.", fr: "Plus de jeux à venir bientôt.", de: "Weitere Spiele folgen bald.", es: "Más juegos próximamente.", ru: "Скоро выйдет больше игр.", pt: "Mais jogos em breve." });
raw.gamesBackHome = T("← Back to Home", { "zh-CN": "← 返回首页", "zh-TW": "← 返回首頁", ja: "← ホームに戻る", ko: "← 홈으로 돌아가기", fr: "← Retour à l'accueil", de: "← Zurück zur Startseite", es: "← Volver al inicio", ru: "← На главную", pt: "← Voltar ao início" });
raw.peerTransferEyebrow = T("Device-to-device sharing", { "zh-CN": "设备点对点分享", "zh-TW": "裝置點對點分享", ja: "端末間共有", ko: "기기 간 공유" });
raw.peerTransferTitle = T("File Transfer Assistant", { "zh-CN": "文件传输助手", "zh-TW": "檔案傳輸助手", ja: "ファイル転送アシスタント", ko: "파일 전송 도우미" });
raw.peerTransferSubtitle = T("Send text, TXT documents, and regular files directly between two computers with progress feedback and local downloads.", { "zh-CN": "在两台电脑之间直接发送文字、TXT 文档和普通文件，并查看进度、在本地下载。", "zh-TW": "在兩台電腦之間直接傳送文字、TXT 文件和一般檔案，並查看進度、在本機下載。", ja: "2台のPC間でテキスト、TXT、通常ファイルを直接送信し、進捗確認とローカル保存ができます。", ko: "두 컴퓨터 사이에서 텍스트, TXT 및 일반 파일을 직접 보내고 진행률을 확인해 로컬로 저장합니다." });
raw.peerStatusIdle = T("Ready to pair", { "zh-CN": "等待配对", "zh-TW": "等待配對", ja: "ペアリング待ち", ko: "페어링 준비" });
raw.peerStatusGathering = T("Creating secure route", { "zh-CN": "正在建立安全路径", "zh-TW": "正在建立安全路徑", ja: "安全な経路を作成中", ko: "보안 경로 생성 중" });
