raw.peerCreateCode = T("Create pairing code", { "zh-CN": "生成配对码", "zh-TW": "產生配對碼", ja: "ペアリングコードを作成", ko: "페어링 코드 만들기" });
raw.peerCreatingCode = T("Creating code…", { "zh-CN": "正在生成…", "zh-TW": "正在產生…", ja: "作成中…", ko: "코드 생성 중…" });
