raw.aigcGpt56UltraDesc = T("Echo Relay is an AI-built signal-routing puzzle about drawing ten-second paths, preserving past echoes, and synchronizing every voice at once.", { "zh-CN": "《回声中继》是一款由 AI 构建的信号路线解谜游戏：绘制十秒路径、保留过去的回声，并让所有声部同时完成中继。", "zh-TW": "《回聲中繼》是一款由 AI 建構的訊號路線解謎遊戲：繪製十秒路徑、保留過去的回聲，並讓所有聲部同時完成中繼。", ja: "『Echo Relay』は、10秒間の信号経路を描き、過去のエコーを保存し、すべてのパートを同時に同期させる AI 制作のパズルゲームです。", ko: "Echo Relay는 10초 신호 경로를 그리고 과거의 메아리를 보존하며 모든 파트를 동시에 동기화하는 AI 제작 퍼즐 게임입니다." });
raw.aigcKimiTitle = T("Kimi 2.6 Code", {});
raw.aigcKimiDesc = T("An AI fully autonomous web operations project powered by Kimi 2.6 Code, exploring self-directed webgame building, deployment, and iteration.", { "zh-CN": "由 Kimi 2.6 Code 驱动的 AI 全自主运维 Web 项目，探索 Webgame 的自主构建、部署与迭代。", "zh-TW": "由 Kimi 2.6 Code 驅動的 AI 全自主運維 Web 專案，探索 Webgame 的自主建構、部署與迭代。", ja: "Kimi 2.6 Code による AI 完全自律 Web 運用プロジェクト。Webgame の自律的な構築、デプロイ、反復を探ります。", ko: "Kimi 2.6 Code 기반의 AI 완전 자율 Web 운영 프로젝트로, Webgame의 자율 구축, 배포, 반복을 탐색합니다.", fr: "Un projet Web entièrement autonome par IA avec Kimi 2.6 Code, explorant la création, le déploiement et l'itération de Webgames.", de: "Ein vollständig autonomes AI-Webbetriebsprojekt mit Kimi 2.6 Code, das Webgame-Erstellung, Deployment und Iteration untersucht.", es: "Un proyecto web de operación totalmente autónoma por IA con Kimi 2.6 Code, explorando creación, despliegue e iteración de Webgames.", ru: "Полностью автономный AI-проект веб-операций на Kimi 2.6 Code, исследующий создание, развертывание и итерации Webgame.", pt: "Um projeto web totalmente autônomo por IA com Kimi 2.6 Code, explorando criação, implantação e iteração de Webgames." });
raw.aigcGptMediumTitle = T("GPT 5.5 Medium", { "zh-CN": "GPT 5.5 Medium 普通版", "zh-TW": "GPT 5.5 Medium 普通版" });
raw.aigcGptMediumDesc = T("A standard GPT 5.5 Medium AI fully autonomous web operations project for webgame production, testing, and release flow.", { "zh-CN": "普通版 GPT 5.5 Medium 的 AI 全自主运维 Web 项目，用于 Webgame 制作、测试与发布流程。", "zh-TW": "普通版 GPT 5.5 Medium 的 AI 全自主運維 Web 專案，用於 Webgame 製作、測試與發布流程。", ja: "標準の GPT 5.5 Medium による AI 完全自律 Web 運用プロジェクト。Webgame 制作、テスト、公開フローに対応します。", ko: "표준 GPT 5.5 Medium 기반 AI 완전 자율 Web 운영 프로젝트로, Webgame 제작, 테스트, 릴리스 흐름을 다룹니다.", fr: "Un projet Web entièrement autonome par IA avec GPT 5.5 Medium standard, pour la production, les tests et la publication de Webgames.", de: "Ein standardmäßiges GPT 5.5 Medium AI-Webbetriebsprojekt für Webgame-Produktion, Tests und Release-Abläufe.", es: "Un proyecto web de operación totalmente autónoma por IA con GPT 5.5 Medium estándar para producción, pruebas y publicación de Webgames.", ru: "Стандартный AI-проект автономных веб-операций на GPT 5.5 Medium для производства, тестирования и релизного процесса Webgame.", pt: "Um projeto web totalmente autônomo por IA com GPT 5.5 Medium padrão para produção, testes e fluxo de lançamento de Webgames." });
raw.aigcGptMaxTitle = T("GPT 5.5 Extra High", {});
raw.aigcGptMaxDesc = T("A GPT 5.5 Extra High AI fully autonomous web operations project for deeper planning, higher-reasoning iteration, and webgame delivery.", { "zh-CN": "GPT 5.5 Extra High 的 AI 全自主运维 Web 项目，面向更深规划、更高推理迭代与 Webgame 交付。", "zh-TW": "GPT 5.5 Extra High 的 AI 全自主運維 Web 專案，面向更深規劃、更高推理迭代與 Webgame 交付。", ja: "GPT 5.5 Extra High による AI 完全自律 Web 運用プロジェクト。より深い計画、高推論の反復、Webgame 配信を扱います。", ko: "GPT 5.5 Extra High 기반 AI 완전 자율 Web 운영 프로젝트로, 더 깊은 계획, 고추론 반복, Webgame 제공을 다룹니다.", fr: "Un projet Web entièrement autonome par IA avec GPT 5.5 Extra High, pour une planification plus profonde, une itération à raisonnement élevé et la livraison de Webgames.", de: "Ein GPT 5.5 Extra High AI-Webbetriebsprojekt für tiefere Planung, reasoning-stärkere Iteration und Webgame-Auslieferung.", es: "Un proyecto web de operación totalmente autónoma por IA con GPT 5.5 Extra High para planificación profunda, iteración de alto razonamiento y entrega de Webgames.", ru: "AI-проект автономных веб-операций на GPT 5.5 Extra High для более глубокого планирования, итераций с высоким уровнем рассуждения и доставки Webgame.", pt: "Um projeto web totalmente autônomo por IA com GPT 5.5 Extra High para planejamento mais profundo, iteração de alto raciocínio e entrega de Webgames." });
