raw.aigcMoreSoon = T("More AIGC experiments will be added as the lab grows.", { "zh-CN": "更多 AIGC 实验会随着实验室成长继续加入。", "zh-TW": "更多 AIGC 實驗會隨著實驗室成長繼續加入。", ja: "ラボの成長に合わせて、さらに AIGC 実験を追加します。", ko: "랩이 성장함에 따라 더 많은 AIGC 실험이 추가됩니다.", fr: "D'autres expériences AIGC seront ajoutées à mesure que le laboratoire grandit.", de: "Weitere AIGC-Experimente werden mit dem Wachstum des Labs ergänzt.", es: "Se añadirán más experimentos AIGC a medida que el laboratorio crezca.", ru: "По мере роста лаборатории будут добавляться новые AIGC-эксперименты.", pt: "Mais experimentos AIGC serão adicionados conforme o laboratório cresce." });
