raw.aboutCopyright = T("Copyright © 2026 Mirako Company. Developed by Hanazar Ochikawa.", { "zh-CN": "版权所有 © 2026 Mirako Company. 开发者 Hanazar Ochikawa。", "zh-TW": "版權所有 © 2026 Mirako Company. 開發者 Hanazar Ochikawa。", ja: "Copyright © 2026 Mirako Company. Developed by Hanazar Ochikawa.", ko: "Copyright © 2026 Mirako Company. Developed by Hanazar Ochikawa.", fr: "Copyright © 2026 Mirako Company. Développé par Hanazar Ochikawa.", de: "Copyright © 2026 Mirako Company. Entwickelt von Hanazar Ochikawa.", es: "Copyright © 2026 Mirako Company. Desarrollado por Hanazar Ochikawa.", ru: "Copyright © 2026 Mirako Company. Разработано Hanazar Ochikawa.", pt: "Copyright © 2026 Mirako Company. Desenvolvido por Hanazar Ochikawa." });
raw.aboutPrivacy = T("Settings and logs stay on this device. Temporary Share uploads only browser-encrypted ciphertext; secret keys remain in the URL fragment and are not uploaded.", { "zh-CN": "设置与日志保存在本设备。临时分享只上传浏览器加密后的密文；密钥保留在网址片段中，不会上传。", "zh-TW": "設定與記錄儲存在本裝置。臨時分享只上傳瀏覽器加密後的密文；金鑰保留在網址片段中，不會上傳。", ja: "設定とログはこの端末に保存されます。一時共有でアップロードされるのはブラウザで暗号化されたデータだけで、秘密鍵は URL フラグメントに残り送信されません。", ko: "설정과 로그는 이 기기에 저장됩니다. 임시 공유는 브라우저에서 암호화된 데이터만 업로드하며 비밀 키는 URL 조각에 남아 업로드되지 않습니다.", fr: "Les réglages et journaux restent sur cet appareil. Le partage temporaire ne téléverse que des données chiffrées par le navigateur ; les clés secrètes restent dans le fragment de l’URL.", de: "Einstellungen und Protokolle bleiben auf diesem Gerät. Temporäre Freigaben laden nur browserseitig verschlüsselte Daten hoch; geheime Schlüssel verbleiben im URL-Fragment.", es: "La configuración y los registros permanecen en este dispositivo. El uso compartido temporal solo sube datos cifrados por el navegador; las claves permanecen en el fragmento de la URL.", ru: "Настройки и журналы остаются на этом устройстве. Временный обмен загружает только зашифрованные браузером данные; секретные ключи остаются во фрагменте URL.", pt: "As configurações e os registros ficam neste dispositivo. O compartilhamento temporário envia apenas dados cifrados pelo navegador; as chaves permanecem no fragmento da URL." });

